alter table public.web_orders add column if not exists match_status text not null default 'matched'; alter table public.web_orders drop constraint if exists web_orders_match_status_check; alter table public.web_orders add constraint web_orders_match_status_check check (match_status in ('matched', 'unmatched', 'already_sold')); alter table public.web_orders add column if not exists marketplace_fee_cents int; alter table public.web_orders add column if not exists marketplace_title text; update public.store_settings set value = 'false'::jsonb where key = 'ebay_disabled'; update public.store_settings ss set value = ( select jsonb_agg(to_jsonb(k) order by k) from ( select distinct lower(btrim(x)) k from jsonb_array_elements_text( case when jsonb_typeof(ss.value) = 'array' then ss.value else '[]'::jsonb end ) x union select 'ebay' union select 'website' ) q where k is not null and k <> '' ) where ss.key = 'online_channels'; update public.store_settings ss set value = coalesce(ss.value, '[]'::jsonb) || '[{"key":"ebay","label":"eBay","aliases":["ebay","e bay"]}]'::jsonb where ss.key = 'marketplace_channels' and not exists ( select 1 from jsonb_array_elements(ss.value) x where x->>'key' = 'ebay' );